insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$Threatening or ongoing processes with high dispute value; existential legal risks$txt$, $txt$Drohende oder laufende Verfahren mit hohem Streitwert; existenzielle Rechtsrisiken$txt$, 0, 2 from public.qv_questions where question_key = $txt$lc-5$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$ft-6$txt$, $txt$What proportion of IT services revenue comes from recurring managed-service retainers versus one-off project work?$txt$, $txt$Welcher Anteil des IT-Services-Umsatzes stammt aus wiederkehrenden Managed-Service-Retainern statt aus Einzelprojekten?$txt$, $txt$Acquirers apply significant valuation discounts to pure project businesses. A retainer base above 40% fundamentally changes the quality-of-earnings narrative.$txt$, $txt$Käufer setzen bei reinen Projektgeschäften deutliche Bewertungsabschläge an. Eine Retainer-Basis über 40% verändert die Quality-of-Earnings-Story grundlegend.$txt$, false, true, 300, array['it_services']::text[], false, null, null from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$financial_transparency$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$Over 50% of revenue from multi-year managed service or retainer contracts; project work fills capacity only$txt$, $txt$Über 50% des Umsatzes aus mehrjährigen Managed-Service- oder Retainer-Verträgen; Projekte füllen nur Kapazitäten$txt$, 2, 0 from public.qv_questions where question_key = $txt$ft-6$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$30-50% recurring retainer revenue; active effort to convert project clients to retained relationships$txt$, $txt$30-50% wiederkehrender Retainer-Umsatz; aktive Umstellung von Projektkunden auf Retainer$txt$, 1, 1 from public.qv_questions where question_key = $txt$ft-6$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$Predominantly project-based; less than 30% recurring; revenue highly dependent on new contract wins$txt$, $txt$Überwiegend projektbasiert; unter 30% wiederkehrend; Umsatz stark von Neuaufträgen abhängig$txt$, 0, 2 from public.qv_questions where question_key = $txt$ft-6$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$mp-5$txt$, $txt$What is your Net Revenue Retention (NRR) rate, and how has Annual Recurring Revenue (ARR) trended over the last 12 months?$txt$, $txt$Wie hoch ist Ihre Net Revenue Retention (NRR) und wie hat sich der ARR in den letzten 12 Monaten entwickelt?$txt$, $txt$NRR above 100% signals that existing customers are expanding - a primary valuation driver for SaaS acquirers. ARR growth trajectory is often more important than absolute revenue.$txt$, $txt$Eine NRR über 100% zeigt, dass Bestandskunden ausbauen - ein zentraler Bewertungstreiber für SaaS-Käufer. Der ARR-Wachstumspfad ist oft wichtiger als der absolute Umsatz.$txt$, false, true, 310, array['saas','hr_tech']::text[], false, null, null from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$market_position$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$NRR above 110%; ARR growing >25% year-on-year; churn well below industry average$txt$, $txt$NRR über 110%; ARR-Wachstum >25% im Jahresvergleich; Churn deutlich unter Branchendurchschnitt$txt$, 2, 0 from public.qv_questions where question_key = $txt$mp-5$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$NRR between 90-110%; ARR stable or growing modestly; churn tracked and managed$txt$, $txt$NRR zwischen 90-110%; ARR stabil oder moderat wachsend; Churn wird erfasst und gesteuert$txt$, 1, 1 from public.qv_questions where question_key = $txt$mp-5$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$NRR below 90%; ARR flat or declining; churn not systematically measured$txt$, $txt$NRR unter 90%; ARR stagnierend oder rückläufig; Churn wird nicht systematisch gemessen$txt$, 0, 2 from public.qv_questions where question_key = $txt$mp-5$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$cyber_own_ip_mix$txt$, $txt$What share of revenue comes from your own managed services and products rather than reselling third-party licences?$txt$, $txt$Welcher Umsatzanteil stammt aus eigenen Managed Services und Produkten statt aus dem Wiederverkauf von Fremdlizenzen?$txt$, $txt$Buyers price own delivery and own IP differently from licence resale: resale revenue carries vendor dependency and thin margins, own services carry the multiple.$txt$, $txt$Käufer bewerten Eigenleistung und eigene IP anders als Lizenz-Resale: Resale-Umsatz trägt Herstellerabhängigkeit und dünne Margen, eigene Services tragen das Multiple.$txt$, false, true, 320, array['cybersecurity']::text[], false, null, null from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$market_position$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$Own delivery dominates; third-party resale below roughly 30% of revenue$txt$, $txt$Eigenleistung dominiert; Fremdlizenz-Resale unter rund 30% des Umsatzes$txt$, 2, 0 from public.qv_questions where question_key = $txt$cyber_own_ip_mix$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$Balanced mix of own delivery and third-party resale$txt$, $txt$Ausgewogener Mix aus Eigenleistung und Fremdlizenz-Resale$txt$, 1, 1 from public.qv_questions where question_key = $txt$cyber_own_ip_mix$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$Revenue predominantly from reselling third-party licences$txt$, $txt$Umsatz überwiegend aus dem Wiederverkauf von Fremdlizenzen$txt$, 0, 2 from public.qv_questions where question_key = $txt$cyber_own_ip_mix$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$cyber_certifications$txt$, $txt$Which security certifications and audit attestations does your company hold?$txt$, $txt$Welche Sicherheitszertifizierungen und Prüfnachweise hält Ihr Unternehmen?$txt$, $txt$In cybersecurity transactions, buyers verify certifications early in due diligence; a current ISO 27001 or SOC 2 report shortens the process and supports the valuation.$txt$, $txt$Bei Cybersecurity-Transaktionen prüfen Käufer Zertifizierungen früh in der Due Diligence; ein aktueller ISO-27001- oder SOC-2-Nachweis verkürzt den Prozess und stützt die Bewertung.$txt$, false, true, 330, array['cybersecurity']::text[], false, null, null from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$processes_scalability$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$ISO 27001 or SOC 2 Type II in place; audits current, renewals scheduled$txt$, $txt$ISO 27001 oder SOC 2 Type II vorhanden; Audits aktuell, Renewals terminiert$txt$, 2, 0 from public.qv_questions where question_key = $txt$cyber_certifications$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$Certification in progress or partial attestations (e.g. TISAX, BSI baseline protection)$txt$, $txt$Zertifizierung läuft oder Teilnachweise (z. B. TISAX, BSI-Grundschutz)$txt$, 1, 1 from public.qv_questions where question_key = $txt$cyber_certifications$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$No formal security certification or attestation$txt$, $txt$Keine formale Sicherheitszertifizierung$txt$, 0, 2 from public.qv_questions where question_key = $txt$cyber_certifications$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$cyber_key_experts$txt$, $txt$How dependent is service delivery on a small number of certified security experts?$txt$, $txt$Wie stark hängt die Leistungserbringung an wenigen zertifizierten Security-Experten?$txt$, $txt$Scarce security talent is a core diligence topic: buyers examine whether delivery survives the departure of individual certified experts.$txt$, $txt$Knappes Security-Personal ist ein Kernthema der Due Diligence: Käufer prüfen, ob die Leistungserbringung den Abgang einzelner zertifizierter Experten übersteht.$txt$, false, true, 340, array['cybersecurity']::text[], false, null, null from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$people_culture$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$Expertise spread across a stable team; key certifications held by several people per domain; cover documented$txt$, $txt$Know-how auf ein stabiles Team verteilt; Schlüsselzertifikate mehrfach je Themenfeld; Vertretung dokumentiert$txt$, 2, 0 from public.qv_questions where question_key = $txt$cyber_key_experts$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$Some concentration on individual experts; deputies partly in place$txt$, $txt$Teilweise Konzentration auf einzelne Experten; Vertretung teilweise geregelt$txt$, 1, 1 from public.qv_questions where question_key = $txt$cyber_key_experts$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$Delivery depends on one or two key experts without documented cover$txt$, $txt$Leistung hängt an ein bis zwei Schlüsselpersonen ohne dokumentierte Vertretung$txt$, 0, 2 from public.qv_questions where question_key = $txt$cyber_key_experts$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$oi-1-fu$txt$, $txt$Is there a documented deputy or succession plan that would allow the business to operate for 90+ days without the owner?$txt$, $txt$Gibt es einen dokumentierten Vertretungs- oder Nachfolgeplan, mit dem das Unternehmen 90+ Tage ohne den Inhaber arbeiten könnte?$txt$, $txt$Even if owner dependency is currently high, a credible written transition plan signals to buyers that you are aware of the risk and have begun addressing it.$txt$, $txt$Auch bei hoher Inhaberabhängigkeit signalisiert ein belastbarer schriftlicher Übergabeplan Käufern, dass das Risiko erkannt und angegangen wird.$txt$, false, true, 350, null, true, $txt$oi-1$txt$, 'score_0' from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$owner_independence$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$Formal written succession plan exists; deputy has been active in key decisions for at least 6 months$txt$, $txt$Formaler schriftlicher Nachfolgeplan vorhanden; die Vertretung ist seit mindestens 6 Monaten in Schlüsselentscheidungen eingebunden$txt$, 2, 0 from public.qv_questions where question_key = $txt$oi-1-fu$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$Deputy identified and partially trained; succession plan drafted but not yet tested$txt$, $txt$Vertretung identifiziert und teilweise eingearbeitet; Nachfolgeplan entworfen, aber noch nicht getestet$txt$, 1, 1 from public.qv_questions where question_key = $txt$oi-1-fu$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$No deputy or succession plan; owner is sole decision-maker with no documented handover procedure$txt$, $txt$Keine Vertretung und kein Nachfolgeplan; der Inhaber entscheidet allein, ohne dokumentierte Übergabe$txt$, 0, 2 from public.qv_questions where question_key = $txt$oi-1-fu$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$cs-1-fu$txt$, $txt$What would be the quantified financial impact if your largest customer were lost, and is there an active diversification strategy in place?$txt$, $txt$Welche quantifizierte finanzielle Auswirkung hätte der Verlust Ihres größten Kunden, und gibt es eine aktive Diversifizierungsstrategie?$txt$, $txt$Concentration risk must be quantified and mitigated, not just acknowledged. Buyers need to see that you understand the exposure and are actively reducing it.$txt$, $txt$Konzentrationsrisiko muss quantifiziert und gemindert werden, nicht nur benannt. Käufer wollen sehen, dass das Exposure verstanden und aktiv reduziert wird.$txt$, false, true, 360, null, true, $txt$cs-1$txt$, 'score_0' from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$customer_supplier$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$Financial impact quantified; active diversification programme underway; retention agreements signed with top clients$txt$, $txt$Finanzielle Auswirkung quantifiziert; aktives Diversifizierungsprogramm läuft; Bindungsvereinbarungen mit Top-Kunden unterzeichnet$txt$, 2, 0 from public.qv_questions where question_key = $txt$cs-1-fu$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$Impact understood informally; some retention measures in place; diversification on the roadmap$txt$, $txt$Auswirkung informell verstanden; einzelne Bindungsmaßnahmen vorhanden; Diversifizierung auf der Roadmap$txt$, 1, 1 from public.qv_questions where question_key = $txt$cs-1-fu$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$No formal analysis of concentration risk; no diversification strategy; relationship relies solely on personal owner ties$txt$, $txt$Keine formale Analyse des Konzentrationsrisikos; keine Diversifizierungsstrategie; die Beziehung beruht allein auf persönlichen Kontakten des Inhabers$txt$, 0, 2 from public.qv_questions where question_key = $txt$cs-1-fu$txt$;
insert into public.qv_questions (version_id, category_id, question_key, text_en, text_de, info_en, info_de, is_red_flag, is_active, sort_order, sectors, is_follow_up, follow_up_question_key, follow_up_condition) select v.id, c.id, $txt$ft-2-fu$txt$, $txt$Are monthly or quarterly management accounts maintained, and have they been reviewed by an external accountant?$txt$, $txt$Werden monatliche oder quartalsweise Management Accounts geführt und wurden sie von einem externen Buchhalter geprüft?$txt$, $txt$In the absence of full audited accounts, buyers look for the next-best evidence of financial rigour. Regularly reviewed management accounts significantly reduce perceived financial risk.$txt$, $txt$Ohne vollständig testierte Abschlüsse suchen Käufer den nächstbesten Nachweis finanzieller Disziplin. Regelmäßig geprüfte Management Accounts senken das wahrgenommene Finanzrisiko deutlich.$txt$, false, true, 370, null, true, $txt$ft-2$txt$, 'score_lte_1' from public.questionnaire_versions v join public.qv_categories c on c.version_id = v.id and c.key = $txt$financial_transparency$txt$ where v.version = 1;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'optimal', $txt$Monthly management accounts produced and reviewed by an external accountant quarterly; variance analysis documented$txt$, $txt$Monatliche Management Accounts, quartalsweise von einem externen Buchhalter geprüft; Abweichungsanalyse dokumentiert$txt$, 2, 0 from public.qv_questions where question_key = $txt$ft-2-fu$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'good', $txt$Quarterly management accounts exist; external accountant involved at year-end only$txt$, $txt$Quartalsweise Management Accounts vorhanden; externer Buchhalter nur zum Jahresende eingebunden$txt$, 1, 1 from public.qv_questions where question_key = $txt$ft-2-fu$txt$;
insert into public.question_options (question_id, option_key, text_en, text_de, score, sort_order) select id, 'low', $txt$No management accounts; financials prepared only for tax purposes once a year$txt$, $txt$Keine Management Accounts; Zahlen werden nur einmal jährlich für steuerliche Zwecke erstellt$txt$, 0, 2 from public.qv_questions where question_key = $txt$ft-2-fu$txt$;
